<?php
$forms=safeRun($pdo,'SELECT * FROM progress_forms WHERE programme_type=? AND (semester_id IS NULL OR semester_id=?) ORDER BY week_number,created_at',[$pt,$currentSemesterId])->fetchAll();
$mySubs=safeRun($pdo,'SELECT * FROM progress_submissions WHERE student_id=?',[$studentId])->fetchAll();$subByForm=array_column($mySubs,null,'progress_form_id');$error=$_GET['error']??null;
?>
<?php if($error): ?><div class="alert alert-danger small">Progress report upload failed: <?= e($error) ?>.</div><?php endif; ?>
<div class="row g-3"><?php foreach($forms as $f):$mySub=$subByForm[$f['id']]??null;$closed=$f['deadline']&&date('Y-m-d')>$f['deadline']; ?><div class="col-md-6"><div class="card-fy h-100"><div class="d-flex justify-content-between align-items-start mb-2"><h6 class="fw-bold mb-0"><?= e($f['title']) ?></h6><span class="badge-fy badge-<?= $mySub?'success':($closed?'danger':'warning') ?>"><?= $mySub?'Submitted':($closed?'Closed':'Pending') ?></span></div><p class="small text-muted"><?= e($f['description']) ?></p><?php if($f['deadline']): ?><p class="small text-muted">Due <?= date('M j, Y',strtotime($f['deadline'])) ?></p><?php endif; ?><?php if($f['file_path']): ?><a target="_blank" class="small d-inline-block mb-2" href="<?= secureFileUrl((int)$f['id'],'progress_form') ?>">Download form template</a><?php endif; ?>
<?php if($mySub): ?><div class="d-flex justify-content-between p-2 rounded-3" style="background:var(--bg-soft)"><span class="small"><?= e($mySub['file_name']) ?></span><a target="_blank" class="btn-fy-outline btn-sm" href="<?= secureFileUrl((int)$mySub['id'],'progress_submission') ?>">View</a></div><?php endif; ?>
<?php if(!$closed): ?><form method="POST" enctype="multipart/form-data" class="d-flex gap-2 mt-2"><?= csrfField() ?><input type="hidden" name="action" value="submit_progress_report"><input type="hidden" name="progress_form_id" value="<?= $f['id'] ?>"><input type="file" name="file" class="form-control-fy flex-grow-1" required><button class="btn-fy-orange"><?= $mySub?'Replace':'Upload' ?></button></form><?php endif; ?>
</div></div><?php endforeach; ?><?php if(empty($forms)): ?><div class="col-12"><div class="card-fy text-center py-5 text-muted">No progress forms issued.</div></div><?php endif; ?></div>
